Tests.EqualCheck("match nested groups referencing outer group 1", true, matchPattern("hello world hello world", `((hello) (world)) \1`))
Tests.EqualCheck("match nested groups referencing first inner group 2", true, matchPattern("hello world hello", `((hello) (world)) \2`))
Tests.EqualCheck("match nested groups referencing second inner group 3", true, matchPattern("hello world world", `((hello) (world)) \3`))
Tests.EqualCheck("match nested groups referencing outer and inner sequentially", true, matchPattern("hello world hello world hello world", `((hello) (world)) \1 \2 \3`))
Tests.EqualCheck("do not match mismatched nested reference", false, matchPattern("hello world foo", `((hello) (world)) \2`))
Tests.EqualCheck("match outer quotes and inner text", true, matchPattern("'cat' 'cat' cat", `^('([^']*)') \1 \2$`))
Tests.EqualCheck("do not match when outer quotes match but inner content differs", false, matchPattern("'cat' 'cat' dog", `^('([^']*)') \1 \2$`))
Tests.EqualCheck("match nested bracket key-value pair", true, matchPattern("[a=1] [a=1] a 1", `^(\[(\w+)=(\d+)\]) \1 \2 \3$`))
Tests.EqualCheck("do not match when key in nested group differs", false, matchPattern("[a=1] [a=1] b 1", `^(\[(\w+)=(\d+)\]) \1 \2 \3$`))
Tests.EqualCheck("match three levels of nesting", true, matchPattern("a a a", `(((a))) \1 \2`))
Tests.EqualCheck("match nested group with word quantifier", true, matchPattern("foo 123 foo 123 foo", `^(([a-z]+) (\d+)) \1 \2$`))
Tests.EqualCheck("do not match when nested word quantifier does not match reference", false, matchPattern("foo 123 foo 123 bar", `^(([a-z]+) (\d+)) \1 \2$`))
Tests.EqualCheck("match nested group with alternation", true, matchPattern("start cat cat", `(start (cat|dog)) \2`))
Tests.EqualCheck("match nested group with alternation second branch", true, matchPattern("start dog dog", `(start (cat|dog)) \2`))
Tests.EqualCheck("do not match nested group with incorrect alternation branch", false, matchPattern("start cat dog", `(start (cat|dog)) \2`))
Tests.EqualCheck("empty pattern matches any line", true, matchPattern("hello", ""))
